    int rc = sqlite3_prepare_v2(db, query.c_str(), -1, &stmt, 0);
    if (rc != SQLITE_OK) {
        return 1;
    }

    // Safe binding of parameters
    rc = sqlite3_bind_text(stmt, 1, "user123", -1, SQLITE_STATIC);
    rc = sqlite3_bind_text(stmt, 2, "password123", -1, SQLITE_STATIC);

    if (rc != SQLITE_OK) {
        return 1;
    }

    // Execute the statement
